use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,fmt::Write,path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-indexed-mixed-top176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-indexed-mixed-top176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p))}else if p.is_file(){v.push(p)}}v.sort();v}
fn gzip(p:&Path,b:&[u8]){let temp=p.with_extension("temporary");fs::write(&temp,b).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&temp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let out=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(out.status.success());assert_eq!(out.stdout,b);fs::remove_file(temp).unwrap();}
fn main(){let review=read(r("review.json"));assert_eq!(review["passed"],true);assert_eq!(review["component_gate_passed"],false);let out=Path::new(O);assert!(!out.exists());fs::create_dir_all(out.join("artifacts")).unwrap();
 let mut source=BTreeMap::new();for p in walk(&r("source")){let b=fs::read(&p).unwrap();let hex=b.iter().map(|v|format!("{v:02x}")).collect::<String>();let restored=hex.as_bytes().chunks_exact(2).map(|p|u8::from_str_radix(std::str::from_utf8(p).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(restored,b);source.insert(p.strip_prefix(r("source")).unwrap().display().to_string(),json!({"hex":hex,"length":b.len(),"sha256":hash(&b)}));}assert_eq!(source.len(),178);gzip(&out.join("artifacts/source178.json.gz"),&serde_json::to_vec(&source).unwrap());
 let allowed=|p:&Path|matches!(p.extension().and_then(|s|s.to_str()),Some("rs"|"md"|"json"|"log"|"toml"|"lock"|"csv"));let mut files=vec![];for n in["setup.rs","native-tests.rs","design.md","algebra.rs","prepare.rs","protocol.md","source-audit.json","environment.json","fixtures.json","cases.json","jobs.json","identities.json","build-plan.json","build-pins.json","algebra-plan.json","algebra-pins.json","capture-plan.json","capture-pins.json","campaign.rs","analyze.rs","analysis.json","callers.json","symbols.json","review.rs","review-initial.rs","review-initial-failure.json","review.json","report-draft.md","publish.rs"]{files.push(r(n));}
 for d in["driver","native","algebra-check","runs","stat"]{files.extend(walk(&r(d)).into_iter().filter(|p|allowed(p)));}for j in read(r("jobs.json")).as_array().unwrap(){if let Some(p)=j["reused_from"].as_str(){files.extend(walk(Path::new(p)).into_iter().filter(|p|allowed(p)));}}
 let mut receipts=BTreeMap::new();for p in files{let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);receipts.insert(p.display().to_string(),json!({"utf8":text,"length":b.len(),"sha256":hash(&b)}));}let n=receipts.len();gzip(&out.join("artifacts/receipts-and-helpers.json.gz"),&serde_json::to_vec(&receipts).unwrap());
 for shape in["1x2","2x2"]{for arm in["FROZEN","OFF","ON"]{let name=format!("cycles-{shape}-B-w32-{arm}.data");gzip(&out.join("artifacts").join(format!("{name}.gz")),&fs::read(r("perf").join(name)).unwrap());}}
 for f in["analysis.json","review.json","source-audit.json","identities.json","design.md","protocol.md","algebra.rs","native-tests.rs","setup.rs","campaign.rs","analyze.rs","review.rs","publish.rs"]{fs::copy(r(f),out.join("artifacts").join(f)).unwrap();}
 fs::copy(r("report-draft.md"),out.join("README.md")).unwrap();let mut sums=String::new();let files=walk(out);for p in&files{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Published{}files/178source/{n}exactUTF8members/sixlosslessprofiles; allarchivebytes roundtrip checked; no privatepoint/scalar/key/witnessarrays or binarylibraries.",files.len()+1);
}
